/* ── Projects Page ── */
.projects-container {
  display: flex;
  flex-direction: column;
  gap: 2rem;
  padding: 1rem 0;
}

.project-card {
  display: flex;
  flex-direction: row;
  background-color: #ffffff20;
  border: 1px solid var(--pebble-grey);
  border-radius: 10px;
  overflow: hidden;
  box-shadow: 0 2px 12px rgba(0,0,0,0.08);
  transition: box-shadow 0.2s ease;
}

.project-card:hover {
  box-shadow: 0 4px 20px rgba(0,0,0,0.15);
  border-color: var(--sage-green);
}

.project-image {
  width: 40%;
  min-height: 220px;
  overflow: hidden;
  flex-shrink: 0;
}

.project-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.project-info {
  padding: 1.5rem 2rem;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.project-info h3 {
  font-family: 'Playfair Display', serif;
  color: var(--obsidian);
  margin-bottom: 0.4rem;
}

.project-tag {
  font-size: 0.8rem;
  color: var(--sage-green);
  font-weight: 500;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  margin-bottom: 0.75rem;
}

.project-info p {
  color: var(--pebble-grey);
  line-height: 1.7;
}

/* ── Responsive: stack on mobile ── */
@media (max-width: 600px) {
  .project-card {
    flex-direction: column;
  }
  .project-image {
    width: 100%;
    min-height: 180px;
  }
}
/* To add a new project later, just copy and paste one of the card blocks and update the image path, title, tags, and description. To use a placeholder image in the meantime, you can use https://placehold.co/600x400 as the src until you have real photos! */
